<?php
namespace Tests\Feature;use App\Models\{NewsArticle,NewsCategory,NewsSource};use App\Services\News\NewsProcessingService;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class NewsIntelligenceTest extends TestCase{use RefreshDatabase;public function test_latest_page_and_ajax_are_public():void{$c=NewsCategory::create(['name'=>'Technology','slug'=>'technology']);$s=NewsSource::create(['name'=>'Official','source_type'=>'official']);NewsArticle::create(['category_id'=>$c->id,'source_id'=>$s->id,'title'=>'Cloud hiring expands','slug'=>'cloud-hiring','excerpt'=>'Cloud roles','source_url'=>'https://github.blog/example','is_published'=>true,'published_at'=>now()]);$this->get('/latest')->assertOk()->assertSee('Cloud hiring expands');$this->getJson('/latest/ajax?search=Cloud')->assertOk()->assertJsonCount(1,'data');}public function test_processor_categorizes_and_scores_article():void{$c=NewsCategory::create(['name'=>'Technology','slug'=>'technology']);NewsCategory::create(['name'=>'Data Centers','slug'=>'data-centers']);$a=NewsArticle::create(['category_id'=>$c->id,'title'=>'India data center cloud expansion','slug'=>'data-center','excerpt'=>'AWS cloud and Kubernetes jobs','raw_content'=>'India data center AWS cloud Kubernetes hiring','source_url'=>'https://github.blog/data-center','processing_status'=>'fetched']);app(NewsProcessingService::class)->process($a);$this->assertSame('data-centers',$a->fresh()->category->slug);$this->assertSame('processed',$a->fresh()->processing_status);$this->assertGreaterThan(30,$a->fresh()->relevance_score);}}
